<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;
use CetechDeliveryEngine\Presentation\Shared\CustomerPolicyRenderer as Renderer;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

final class CustomerPolicyRendererTest extends TestCase {
	public static function view(string$status='ready'):array{$f=['disposition'=>'assigned','customer_title'=>'Returns — سياسة','summary'=>"Summary\nSecond line",'full_text'=>'<b>literal markup</b> & "quoted"','exceptions'=>'Keep original packaging'];return['version'=>1,'status'=>$status,'ticket'=>'saved'===$status?null:'cp1p.'.str_repeat('a',32).'.'.str_repeat('b',64),'families'=>(object)['return_policy_v1'=>$f,'refund_policy_v1'=>$f]];}
	public function test_literal_markup_unicode_and_all_four_fields_are_escaped_not_executed():void{$v=self::view();$html=Renderer::html($v);self::assertStringContainsString('&lt;b&gt;literal markup&lt;/b&gt; &amp; &quot;quoted&quot;',$html);self::assertStringNotContainsString('<b>literal markup</b>',$html);self::assertStringContainsString('Returns — سياسة',$html);self::assertSame(2,substr_count($html,'<details>'));self::assertStringContainsString("Summary\nSecond line",$html);self::assertStringContainsString('Keep original packaging',Renderer::plain($v));self::assertStringNotContainsString('cp1p',Renderer::plain($v));}
	public static function corruptions():array{$v=self::view();$out=[];$push=static function(string$name,array$bad)use(&$out):void{$out[$name]=[$bad];};foreach(['name','author','reason','reference','current_state','html']as$key){$b=$v;$b[$key]='PRIVATE';$push('envelope-'.$key,$b);$b=$v;$f=clone$b['families'];$f->return_policy_v1[$key]='PRIVATE';$b['families']=$f;$push('family-'.$key,$b);}foreach(['version','status','ticket','families']as$key){$b=$v;unset($b[$key]);$push('missing-'.$key,$b);}foreach([null,2,'1',true,1.0]as$i=>$value){$b=$v;$b['version']=$value;$push('version-'.$i,$b);}foreach(['unresolved','none',false,[]]as$i=>$value){$b=$v;$b['status']=$value;$push('status-'.$i,$b);}foreach([[],new \stdClass(),false,1,str_repeat('t',257),"bad\0ticket"]as$i=>$value){$b=$v;$b['ticket']=$value;$push('ticket-'.$i,$b);}foreach(['saved','unavailable','unsupported']as$status){$b=$v;$b['status']=$status;$push('forbidden-ticket-'.$status,$b);}foreach(Renderer::FIELDS as$field){foreach([null,1,[],"bad\0text", "\xFF"]as$i=>$value){$b=$v;$f=clone$b['families'];$f->return_policy_v1[$field]=$value;$b['families']=$f;$push('text-'.$field.'-'.$i,$b);}}$b=$v;$b['families']=(object)['return_policy_v1'=>$v['families']->return_policy_v1];$push('missing-family',$b);$b=$v;$b['families']->return_policy_v1['disposition']='unresolved';$push('unresolved-ready',$b);return$out;}
	#[DataProvider('corruptions')]
	public function test_unknown_private_missing_malformed_or_future_public_shapes_are_not_rendered(array$bad):void{self::assertNull(Renderer::normalize($bad));self::assertSame('',Renderer::html($bad));self::assertSame('',Renderer::plain($bad));self::assertSame('',Renderer::ticket_input($bad,'delivery:1'));}
	public function test_nonassigned_states_cannot_smuggle_authored_text():void{foreach(['disabled','not_assigned','unresolved']as$state){$v=self::view('unavailable');$v['ticket']=null;$v['families']->return_policy_v1=['disposition'=>$state,...array_fill_keys(Renderer::FIELDS,null)];self::assertNotNull(Renderer::normalize($v));$v['families']->return_policy_v1['summary']='PRIVATE';self::assertNull(Renderer::normalize($v));}}
	public function test_exact_utf8_byte_limits_and_plus_one_are_closed():void{$v=self::view();foreach(Renderer::FAMILIES as$code){$v['families']->{$code}=['disposition'=>'assigned','customer_title'=>'T','summary'=>'','full_text'=>str_repeat('x',131071),'exceptions'=>''];}self::assertNotNull(Renderer::normalize($v));$v['families']->return_policy_v1['full_text'].='x';self::assertNull(Renderer::normalize($v));$v=self::view();$v['ticket']=str_repeat('é',128);self::assertNotNull(Renderer::normalize($v));$v['ticket'].='x';self::assertNull(Renderer::normalize($v));}
	public function test_saved_grouping_keeps_explicit_item_associations_and_no_form_or_ticket():void{$v=self::view('saved');$items=[['label'=>'Item 1: <widget> × 2','view'=>$v],['label'=>'Item 2: Cable × 1','view'=>$v]];$html=Renderer::saved_html($items);self::assertSame(2,substr_count($html,'data-cetech-de-policy-family='));self::assertStringContainsString('Item 1: &lt;widget&gt; × 2, Item 2: Cable × 1',$html);self::assertStringNotContainsString('<form',$html);self::assertStringNotContainsString('<input',$html);self::assertStringContainsString('<b>literal markup</b>',Renderer::saved_plain($items));$items[1]['view']['families']=clone$v['families'];$items[1]['view']['families']->refund_policy_v1['summary']='Different';self::assertSame(4,substr_count(Renderer::saved_html($items),'data-cetech-de-policy-family='));}
	public function test_review_controls_use_escaped_transport_only():void{$html=Renderer::ticket_input(self::view(),'offer"<>');self::assertStringContainsString('offer&quot;&lt;&gt;',$html);self::assertStringNotContainsString('Policies',$html);self::assertSame('',Renderer::ticket_input(self::view('saved'),'offer'));self::assertSame('',Renderer::ticket_input(self::view(),''));$option=Renderer::option_html(self::view(),'offer"<>');self::assertStringStartsWith('<div data-cetech-de-policy-option="offer&quot;&lt;&gt;">',$option);self::assertStringContainsString($html,$option);self::assertSame('',Renderer::option_html(null,'offer'));self::assertSame('',Renderer::option_html(self::view(),''));}
	public function test_schema_closes_each_public_object_and_marks_read_only():void{$s=Renderer::public_schema();self::assertTrue($s['readonly']);self::assertFalse($s['additionalProperties']);self::assertSame(['version','status','ticket','families'],$s['required']);self::assertSame(Renderer::FAMILIES,$s['properties']['families']['required']);foreach(Renderer::FAMILIES as$family){self::assertFalse($s['properties']['families']['properties'][$family]['additionalProperties']);self::assertSame(['disposition',...Renderer::FIELDS],$s['properties']['families']['properties'][$family]['required']);}}
}
